class Solution {
    private int[] memo;
    public int countArrangement(int n) {
        memo = new int[1 << n];
        Arrays.fill(memo, -1);
        return dfs(0, n);
    }
    private int dfs(int mask, int n) {
        if (mask == (1 << n) - 1) return 1;
        if (memo[mask] != -1) return memo[mask];
        int pos = Integer.bitCount(mask) + 1;
        int total = 0;
        for (int i = 1; i <= n; ++i) {
            if ((mask & (1 << (i - 1))) == 0) {
                if (i % pos == 0 || pos % i == 0) {
                    total += dfs(mask | (1 << (i - 1)), n);
                }
            }
        }
        return memo[mask] = total;
    }
}

var countArrangement = function(n) {
    const memo = new Int32Array(1 << n).fill(-1);
    function dfs(mask) {
        if (mask === (1 << n) - 1) return 1;
        if (memo[mask] !== -1) return memo[mask];
        let count = 0;
        let temp = mask;
        while (temp > 0) {
            count += temp & 1;
            temp >>= 1;
        }
        const pos = count + 1;
        let total = 0;
        for (let i = 1; i <= n; ++i) {
            if (!(mask & (1 << (i - 1)))) {
                if (i % pos === 0 || pos % i === 0) {
                    total += dfs(mask | (1 << (i - 1)));
                }
            }
        }
        return memo[mask] = total;
    }
    return dfs(0);
};
